     "code": "from google import genai\nfrom replay import Recorder, load_replies\n\n# once, with a key: run the real agent and save its replies\nrun_agent(Recorder(genai.Client(), \"tests/replies_4471.jsonl\"), \"Where is order 4471?\")\n\n# from then on, free: play them back\ndef test_4471_replayed():\n    fake = FakeClient(*load_replies(\"tests/replies_4471.jsonl\"))\n    assert \"ship\" in run_agent(fake, \"Where is order 4471?\").lower()",
